!function(t){function r(r){for(var a,n,m=r[0],o=r[1],u=r[2],s=0,g=[];s<m.length;s++)n=m[s],Object.prototype.hasOwnProperty.call(i,n)&&i[n]&&g.push(i[n][0]),i[n]=0;for(a in o)Object.prototype.hasOwnProperty.call(o,a)&&(t[a]=o[a]);for(c&&c(r);g.length;)g.shift()();return p.push.apply(p,u||[]),e()}function e(){for(var t,r=0;r<p.length;r++){for(var e,n=p[r],m=!0,o=1;o<n.length;o++)e=n[o],0!==i[e]&&(m=!1);m&&(p.splice(r--,1),t=a(a.s=n[0]))}return t}function a(r){if(n[r])return n[r].exports;var e=n[r]={i:r,l:!1,exports:{}};return t[r].call(e.exports,e,e.exports,a),e.l=!0,e.exports}var n={},i={13:0},p=[];a.m=t,a.c=n,a.d=function(t,r,e){a.o(t,r)||Object.defineProperty(t,r,{enumerable:!0,get:e})},a.r=function(t){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(t,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(t,"__esModule",{value:!0})},a.t=function(t,r){if(1&r&&(t=a(t)),8&r)return t;if(4&r&&"object"==typeof t&&t&&t.__esModule)return t;var e=Object.create(null);if(a.r(e),Object.defineProperty(e,"default",{enumerable:!0,value:t}),2&r&&"string"!=typeof t)for(var n in t)a.d(e,n,function(r){return t[r]}.bind(null,n));return e},a.n=function(t){var r=t&&t.__esModule?function(){return t.default}:function(){return t};return a.d(r,"a",r),r},a.o=function(t,r){return Object.prototype.hasOwnProperty.call(t,r)},a.p="";var m=window.webpackJsonp=window.webpackJsonp||[],o=m.push.bind(m);m.push=r,m=m.slice();for(var u=0;u<m.length;u++)r(m[u]);var c=o;p.push([29,0]),e()}({29:function(t,r,e){"use strict";e.r(r);var a=e(0);Object(a.a)("ru","army",e(30),e(1))},30:function(t){t.exports=JSON.parse('{"category":[{"name":"苏联","link":"ru_shortcut"},{"name":"陆战武器","link":"ru_army"},{"name":"坦克","link":"ru_army#ru_army_tank"}],"model":"T-60/T-70轻型坦克","description":"<h6>综述：</h6><p>在苏联研发的轻型坦克中，就产量来说，除了产量最大的T-26外，此外就是T-60和T-70了，这两种坦克是苏联后期生产的轻型坦克（轻型坦克的终结型号是T-80），针对早期 轻型坦克的动力不足问题，这两种坦克都更换了马力更大的汽油机，对悬挂系统也作了改动，提高了坦克的机动性能（但在越野速度上仍跟不上T-34坦克），另外 装甲也加厚了，防护能力得到了加强，但由于本身结构与配置问题，这两种轻型坦克仍跟不上对手装备的发展，特别是这两型坦克炮塔小，乘员只有二人，车长兼炮手，大大削弱了作战时对驾驶的指挥和对炮火的控制。在苏联卫国战争中，当T-34坦克未能大量参战前，这些坦克仍难敌对方，损失甚大。但由于这些坦克结构简单，能快速并大批制造，在战场上也能通过伏击、侦察和后勤支援等发挥作用，这对战争中急需大量坦克来补充部队的苏军仍是十分有用的。</p><p>据不完全统计，T-60和T-70两种轻型坦克总计生产了近15000辆，直到1943年后期，大量T-34等中型坦克和KV、IS重型坦克出现后才停止生产，1944年春，轻型坦克基本全部退出了苏军装甲部队，余下的轻型坦克转作了侦察和后勤保护用。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{text}}T-60轻型坦克二视图{{image}}imgs/ru/army/ru_army_tankt6070_11.jpg{{text}}1942年7月，东线苏联战场，苏联西南方面军一辆不明单位的T-60轻型坦克；坦克上标记着：“为了祖国”。{{image}}imgs/ru/army/ru_army_tankt6070_12.jpg{{text}}1942年至1943年冬季，东线苏联战场斯大林格勒地区，苏军一辆不明单位的T-60轻型坦克。{{image}}imgs/ru/army/ru_army_tankt6070_13.jpg","description":"<h6>T-60轻型坦克</h6><p>该型坦克原设计是想替代落后的两栖坦克(T-40），但它将原两栖坦克的两栖装置拆除了，所以它只能作一般的轻型坦克用。</p><p>该坦克采用焊接车体，改造后的履带使其在雪地、沼泽和烂泥地的机动性相对较强，可通过车辆无法行驶的深雪地区，尽管由于它所装备的火炮只有20mm口径，火力严重不足，但因在严寒天气中显得很耐用，因此被苏军广泛应用于后勤支援、前线救助和变形炮车。连德军缴获了此类坦克后都会拆掉其炮塔，用作大炮牵引车或物资运输车。</p><p>性能参数（仅供参考）：</p><p>车长：约4.0m，车宽：约2.3m，车高：约1.8m，车重：约5.8t；乘员2人；</p><p>最大车速：44km/h；最大行程：450km以上；发动机为85匹马力汽油机；</p><p>装甲厚度：前装甲：早期为25m，后期增至30mm；</p><p>武器配备：一门20mm火炮，一挺7.62mm机枪。</p><span class=\'custom-document-caption text-secondary\'><strong>外形特点：</strong><ol><li>悬挂系统中是4个大口径的负重轮，早期（1941-1942年款）是条辐式，晚期改为全金属的实心轮（1942-1943年款）。</li><li>炮塔为八边圆锥形，车身显得较低矮。</li></ol></span><p>该坦克在1941年到1942年间共生产了6000多辆，于1943年停产。</p>","caption":""},{"image":"{{text}}T-70轻型坦克四视图{{image}}imgs/ru/army/ru_army_tankt6070_21.jpg{{text}}1942年9月，东线苏联战场，苏联西方面军一辆不明单位（编号为268）的T-70轻型坦克。{{image}}imgs/ru/army/ru_army_tankt6070_22.jpg{{text}}1943年7月，东线苏联库尔斯克战场，苏联第5近卫坦克集团军第18装甲军的一辆T-70轻型坦克。{{image}}imgs/ru/army/ru_army_tankt6070_23.jpg","description":"<h6>T-70轻型坦克</h6><p>T-70轻型坦克在1942年3月开始生产，其底盘是从T-60坦克照搬过来的，只是将后轮驱动改为前轮驱动，为了能快速且大量生产，该坦克基本上采用了成熟的技术，为了提高机动性，该型坦克安装了两台70马力的汽油发动机，速度只比T-60稍有提高，但行程却不如T-60，就其总体而言，该型坦克的性能比T-60并没有太大的提高。</p><p>性能参数（仅供参考）：</p><p>车长：约4.65m，车宽：约2.5m，车高：约2.2m，车重：超过9.0t；乘员2人；</p><p>最大车速：约50km/h； 最大行程：不足450km；发动机为两台70匹马力的汽油机。装甲厚度：10-60mm；</p><p>武器配备：一门45mm火炮，一挺7.62mm机枪。</p><span class=\'custom-document-caption text-secondary\'><strong>外形特点：</strong><ol><li>悬挂系统中是5个大口径的负重轮，早期（1942年款）是条辐式，晚期改为全金属的实心轮（1943年款）。</li><li>炮塔改为用装甲钢板制作，侧面较T-60宽。</li></ol></span><p>截至1944年，该型坦克共生产了约8200辆。</p>","caption":""}],"part2title":"战场上的T-60/T-70坦克","part2description":"<article><p>1941年6月德军大举入侵苏联，大量T-60坦克投入了卫国战争中，但由于其装备的20mm坦克炮火力太弱，装甲防护也差，根本无法抗击德军的正面攻击，战损极大。不过在战场伏击和机动运输中，T-60坦克也是起作用的，苏军第一坦克军指挥官卡图科夫曾回忆：在1942年一次激烈战斗中，该型坦克利用麦田的掩护，成功地渗透到德军后方，突然向德军部队展开攻击，成功地阻止了德军的进攻。而T-70坦克最辉煌的战果是在1943年7月的库尔斯克会战，7月12日，苏联第5近卫坦克集团军与德国纳粹党卫军第2和第3装甲军在普罗克霍罗夫卡村庄前32公里处发生正面冲突，429辆德军坦克和870辆苏军坦克参加了战斗，其中苏军有261辆T-70坦克，这些T-70坦克勇猛地向德军坦克冲击，尽管损失不少，但装备T-70坦克的苏军第31坦克旅仍协同T-34坦克突破了德军坦克的阻击，在这一战役的关键时刻起了一定作用。</p><p>面对德军Ⅲ号与Ⅳ号坦克不断加强的火力和装甲，苏军这二型坦克在战场正面对抗的生存率越来越低，尽管后来又诞生了加强装甲的T-80，但在T-34坦克大量进入战场后，这二型坦克逐步退出了前线的战斗，改作承担训练、侦察与后方机关保护等任务。</p></article>","part2content":[{"image":"imgs/ru/army/ru_army_tankt6070_31.jpg","description":"1941年11月东线战场上，一队隶属苏联西方面军第1近卫军装甲旅的T-60轻型坦克正向前线开进。","caption":""},{"image":"imgs/ru/army/ru_army_tankt6070_32.jpg","description":"1941年11月，东线苏联战场线，一队隶属苏联西方面军第50装甲军的T-60轻型坦克正沿公路行进，赶往前线。","caption":""},{"image":"imgs/ru/army/ru_army_tankt6070_33.jpg","description":"东线苏联战场，一辆被德军50mm坦克炮击毁的苏军T-60坦克，遗弃在阵地上。","caption":""},{"image":"imgs/ru/army/ru_army_tankt6070_34.jpg","description":"1942年11月底，一队苏军的T-60坦克正在穿过一条冰雪河流，相比当时其它的苏军坦克经常在泥泞雪地中抛锚的情况，T-60坦克在深雪中的机动性还算可以的了。","caption":""},{"image":"imgs/ru/army/ru_army_tankt6070_35.jpg","description":"东线苏联战场，苏军第112坦克旅的T-70坦克正在草原上待命，准备向德军发动进攻。","caption":""},{"image":"imgs/ru/army/ru_army_tankt6070_36.jpg","description":"东线苏联战场，一队身穿冬季雪地伪装服的苏联士兵在T-70轻型坦克掩护下准备投入战斗。","caption":""},{"image":"imgs/ru/army/ru_army_tankt6070_37.jpg","description":"1943年7月，东线苏联战场，一队T-70轻型坦克正在跟随一辆领前的T-34中型坦克进入战斗阵地。","caption":""},{"image":"imgs/ru/army/ru_army_tankt6070_38.jpg","description":"1942年7月，在东线苏联南部战场上，被苏军遗弃的一辆T-70轻型坦克（前）和一辆T-34坦克。","caption":""},{"image":"imgs/ru/army/ru_army_tankt6070_39.jpg","description":"1942年秋天，东线苏联斯大林格勒战场，苏军T-70轻型坦克正在支援步兵向德军阵地进攻。","caption":""}]}')}});